def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    if isinstance(params, dict):
        # Named parameters
        in_style = self.SQLParams.in_style
        out_style = self.SQLParams.out_style
        param_mapping = {
            self.SQLParams.in_style: params
        }
        formatted_sql = sql
        for key, value in params.items():
            if in_style == 'named':
                placeholder = f':{key}'
            elif in_style == 'pyformat':
                placeholder = f'%({key})s'
            elif in_style == 'format':
                placeholder = f'%({key})'
            elif in_style == 'numeric':
                raise ValueError("Numeric style with dict params is not supported")
            else:
                raise ValueError(f"Unsupported in-style: {in_style}")

            if out_style == 'named':
                new_placeholder = f':{key}'
            elif out_style == 'pyformat':
                new_placeholder = f'%({key})s'
            elif out_style == 'format':
                new_placeholder = f'%s'
                param_mapping['qmark'] = list(params.values())
            elif out_style == 'numeric':
                new_placeholder = f':{list(params.keys()).index(key)+1}'
            else:
                raise ValueError(f"Unsupported out-style: {out_style}")

            formatted_sql = formatted_sql.replace(placeholder, new_placeholder)

        return formatted_sql, param_mapping.get(out_style, params)

    elif isinstance(params, Sequence):
        # Ordinal parameters
        in_style = self.SQLParams.in_style
        out_style = self.SQLParams.out_style
        formatted_sql = sql
        if in_style == 'numeric':
            placeholders = {i+1: placeholder for i, placeholder in enumerate(sql.split(':'))[1:]}
        elif in_style == 'qmark':
            placeholders = {i+1: '?' for i in range(sql.count('?'))}
        elif in_style == 'format':
            placeholders = {i+1: '%' for i in range(sql.count('%'))}
        else:
            raise ValueError(f"Unsupported in-style: {in_style}")

        new_params = []
        for i, value in enumerate(params, start=1):
            placeholder = placeholders.get(i)
            if out_style == 'named':
                new_placeholder = f':param{i}'
                new_params.append((f'param{i}', value))
            elif out_style == 'pyformat':
                new_placeholder = f'%({i})s'
                new_params.append((f'{i}', value))
            elif out_style == 'format':
                new_placeholder = '%s'
                new_params.append(value)
            elif out_style == 'numeric':
                new_placeholder = f':{i}'
                new_params.append(value)
            else:
                raise ValueError(f"Unsupported out-style: {out_style}")

            if in_style in ['numeric', 'pyformat']:
                formatted_sql = formatted_sql.replace(placeholder, new_placeholder, 1)
            elif in_style == 'qmark':
                formatted_sql = formatted_sql.replace('?', new_placeholder, 1)
            elif in_style == 'format':
                formatted_sql = formatted_sql.replace('%', new_placeholder, 1)

        if out_style in ['named', 'pyformat']:
            return formatted_sql, dict(new_params)
        else:
            return formatted_sql, new_params

    else:
        raise ValueError("params must be a dict or a sequence")

