        raise TypeError("The prior must be an instance of InventoryValidator")

    if set(self.inventory.keys()) != set(prior.inventory.keys()):
        raise ValueError("The prior inventory must have the same keys as the current inventory")

    for key in self.inventory:
        if self.inventory[key] < prior.inventory[key]:
            raise ValueError(f"The value for {key} in the prior inventory must be less than or equal to the current inventory")

    if self.timestamp < prior.timestamp:
        raise ValueError("The timestamp of the prior inventory must be less than or equal to the current inventory timestamp")

