            op, left, right = expr
            if op == '&':
                if isinstance(right, tuple) and len(right) == 3:
                    right_op, right_left, right_right = right
                    if right_op == '|' and left == right_left:
                        new_args.append(left)
                    elif right_op == '&' and left == right_left:
                        new_args.append((op, left, right_right))
                    else:
                        new_args.append(expr)
                else:
                    new_args.append(expr)
            elif op == '|':
                if isinstance(right, tuple) and len(right) == 3:
                    right_op, right_left, right_right = right
