                        new_args.append(left)
                    elif right_op == '|' and left == right_left:
                        new_args.append((op, left, right_right))
                    else:
                        new_args.append(expr)
                else:
                    new_args.append(expr)
            else:
                new_args.append(expr)
        else:
            new_args.append(expr)
    return new_args

