    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from copy import deepcopy

    # Helper function to apply absorption laws
    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                # Absorption: A & (A | B) = A
                if isinstance(right, tuple) and right[0] == '|' and left == right[1]:
                    return left
                # Absorption: A & (B | A) = A
                elif isinstance(right, tuple) and right[0] == '|' and left == right[2]:
                    return left
                # Negative absorption: A & (~A | B) = A & B
                elif isinstance(right, tuple) and right[0] == '|' and isinstance(right[1], tuple) and right[1][0] == '~' and right[1][1] == left:
                    return ('&', left, right[2])
                # Negative absorption: A & (B | ~A) = A & B
                elif isinstance(right, tuple) and right[0] == '|' and isinstance(right[2], tuple) and right[2][0] == '~' and right[2][1] == left:
                    return ('&', left, right[1])
            elif op == '|':
                # Absorption: A | (A & B) = A
                if isinstance(right, tuple) and right[0] == '&' and left == right[1]:
                    return left
                # Absorption: A | (B & A) = A
                elif isinstance(right, tuple) and right[0] == '&' and left == right[2]:
                    return left
                # Negative absorption: A | (~A & B) = A | B
                elif isinstance(right, tuple) and right[0] == '&' and isinstance(right[1], tuple) and right[1][0] == '~' and right[1][1] == left:
                    return ('|', left, right[2])
                # Negative absorption: A | (B & ~A) = A | B
                elif isinstance(right, tuple) and right[0] == '&' and isinstance(right[2], tuple) and right[2][0] == '~' and right[2][1] == left:
                    return ('|', left, right[1])
        return expr

    # Apply absorption laws to each expression in the args
    new_args = []
    for expr in args:
        new_expr = apply_absorption(expr)
        if new_expr != expr:
            # If the expression changed, apply absorption again to the new expression
            new_expr = apply_absorption(new_expr)
        new_args.append(new_expr)

    return new_args

