            }, layout_file, indent=2)

    # Create the '_inventory' directory
    inventory_dir = os.path.join(self.storage_root, 'inventory')
    if not os.path.exists(inventory_dir):
        os.makedirs(inventory_dir)

    # Create the 'objects' directory
    objects_dir = os.path.join(self.storage_root, 'objects')
    if not os.path.exists(objects_dir):
        os.makedirs(objects_dir)

    # Optionally, create a 'storage' directory
    storage_dir = os.path.join(self.storage_root, 'storage')
