            return ruamel.yaml.nodes.MappingNode(
                value1.tag,
                [merge_values(k, v2) for k, vs in merged_mapping.items() for v2 in vs if isinstance(v2, ruamel.yaml.nodes.MappingNode)],
                value1.start_mark,
                value1.end_mark,
                value1.flow_style
            )
        else:
            return value2

    merged_dict = defaultdict(list)
    for key, value in nodes:
        merged_dict[key].append(value)

    result = []
    for key, values in merged_dict.items():
        merged_value = values[0]
        for value in values[1:]:
            merged_value = merge_values(merged_value, value)
        result.append((key, merged_value))

    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import defaultdict

    merged_dict = defaultdict(dict)

    for key_node, value_node in nodes:
        key = key_node.value
        if isinstance(value_node, ruamel.yaml.nodes.MappingNode):
            if key in merged_dict:
                # Deep merge the MappingNode values
                for sub_key_node, sub_value_node in value_node.value:
                    sub_key = sub_key_node.value
                    merged_dict[key][sub_key] = sub_value_node
            else:
                merged_dict[key] = {sub_key_node.value: sub_value_node for sub_key_node, sub_value_node in value_node.value}
        else:
            # For non-MappingNode values, the last value wins
            merged_dict[key] = value_node

    # Convert merged_dict back to the desired list of tuples format
    merged_nodes = []
    for key, value in merged_dict.items():
        if isinstance(value, dict):
            value_node = ruamel.yaml.nodes.MappingNode(
                tag='tag:yaml.org,2002:map',
                value=[(ruamel.yaml.nodes.ScalarNode(tag='tag:yaml.org,2002:str', value=sub_key), sub_value) for sub_key, sub_value in value.items()]
            )
        else:
            value_node = value
        key_node = ruamel.yaml.nodes.ScalarNode(tag='tag:yaml.org,2002:str', value=key)
        merged_nodes.append((key_node, value_node))

    return merged_nodes

