def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    base = len(alphabet)
    if base < 1:
        raise ValueError("Alphabet must contain at least one character.")
    if number < 0:
        raise ValueError("Number must be non-negative.")

    if number == 0:
        result = alphabet[0]
    else:
        result = []
        while number > 0:
            number, digit = divmod(number, base)
            result.append(alphabet[digit])
        result.reverse()

    result_str = ''.join(result)

    if padding is not None and len(result_str) < padding:
        result_str = alphabet[0] * (padding - len(result_str)) + result_str

    return result_str

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    base = len(alphabet)
    if number == 0:
        return alphabet[0] * (padding or 1)

    result = []
    while number > 0:
        number, remainder = divmod(number, base)
        result.append(alphabet[remainder])

    result_str = ''.join(reversed(result))

    if padding is not None:
        result_str = result_str.zfill(padding)

    return result_str

