    import subprocess

    def git(args, error_message):
        output, status = subprocess.getstatusoutput("git {0}".format(args))
        if status != 0:
            raise Exception(error_message, output)
        return output

    ignored_files = git("check-ignore -v {0}".format(ignored), "Failed to determine ignored files").splitlines()
