def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == "always":
        return None

    tokens = frequency.split()
    if len(tokens) != 2:
        raise ValueError("Invalid frequency format")

    try:
        count = int(tokens[0])
    except ValueError:
        raise ValueError("Frequency count must be an integer")

    unit = tokens[1].strip().rstrip('s')  # Remove trailing 's' for plurals
    if unit == "week":
        return datetime.timedelta(weeks=count)
    elif unit == "day":
        return datetime.timedelta(days=count)
    elif unit == "hour":
        return datetime.timedelta(hours=count)
    elif unit == "minute":
        return datetime.timedelta(minutes=count)
    elif unit == "second":
        return datetime.timedelta(seconds=count)
    else:
        raise ValueError("Unknown time unit in frequency: {}".format(unit))

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == "always":
        return None

    import re
    match = re.match(r'^\s*(\d+)\s*(\w+)\s*$', frequency)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    number, unit = match.groups()
    number = int(number)
    unit = unit.lower()

    try:
        if unit in ['second', 'seconds', 'sec', 'secs']:
            return datetime.timedelta(seconds=number)
        elif unit in ['minute', 'minutes', 'min', 'mins']:
            return datetime.timedelta(minutes=number)
        elif unit in ['hour', 'hours', 'hr', 'hrs']:
            return datetime.timedelta(hours=number)
        elif unit in ['day', 'days', 'd']:
            return datetime.timedelta(days=number)
        elif unit in ['week', 'weeks', 'wk', 'wks']:
            return datetime.timedelta(weeks=number)
        elif unit in ['month', 'months', 'mon', 'mons']:
            # Approximation, as months can have different lengths
            return datetime.timedelta(days=number * 30)
        elif unit in ['year', 'years', 'yr', 'yrs']:
            # Approximation, as years can have different lengths
            return datetime.timedelta(days=number * 365)
        else:
            raise ValueError(f"Unknown time unit: {unit}")
    except Exception as e:
        raise ValueError(f"Cannot parse frequency: {frequency}") from e

