def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Get the address info for the host
        host_info = socket.getaddrinfo(host, None)
        # Extract the IP addresses from the address info
        host_ips = {info[4][0] for info in host_info}
        # Get the address info for 'localhost'
        local_info = socket.getaddrinfo('localhost', None)
        # Extract the IP addresses from the localhost info
        local_ips = {info[4][0] for info in local_info}
        # Check if there is any intersection between the host IPs and localhost IPs
        return not host_ips.isdisjoint(local_ips)
    except socket.gaierror:
        # If there's an error resolving the host, return False
        return False

def is_local(host):
