def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("commands must be a list of strings")

    full_command = commands + args

    stderr_setting = subprocess.DEVNULL if hide_stderr else None

    try:
        if verbose:
            print(f"Running: {' '.join(full_command)}")

        result = subprocess.run(
            full_command,
            cwd=cwd,
            stderr=stderr_setting,
            env=env,
            check=True,
            text=True,
            capture_output=verbose
        )

        if verbose:
            print("Output:", result.stdout)

        return result.output if verbose else None

    except subprocess.CalledProcessError as e:
        if verbose:
            print("Error:", e.stderr)
        raise RuntimeError(f"Command {' '.join(full_command)} failed with return code {e.returncode}") from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    output = None
    full_command = commands + args
    try:
        if hide_stderr:
            stderr = subprocess.DEVNULL
        else:
            stderr = subprocess.STDOUT

        process = subprocess.Popen(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=stderr)
        output, _ = process.communicate()

        if process.returncode != 0:
            if verbose:
                raise subprocess.CalledProcessError(process.returncode, full_command, output=output)
            else:
                raise subprocess.CalledProcessError(process.returncode, full_command)

    except subprocess.CalledProcessError as e:
        raise ProgramError(f"Command {' '.join(full_command)} failed with return code {e.returncode}")

    return output.decode('utf-8') if output else ''

