def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging
    import json

    configs = {}
    errors = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            error_record = logging.makeLogRecord({
                'levelno': logging.ERROR,
                'levelname': 'ERROR',
                'name': 'config_loader',
                'msg': f"Configuration file not found: {filename}"
            })
            errors.append(error_record)
            continue

        try:
            with open(filename) as fd:
                config = json.load(fd)
            configs[filename] = config
        except Exception as e:
            error_record = logging.makeLogRecord({
                'levelno': logging.ERROR,
                'levelname': 'ERROR',
                'name': 'config_loader',
                'msg': f"Failed to parse configuration file {filename}: {str(e)}"
            })
            errors.append(error_record)

    if overrides:
        for key, value in overrides.items():
            for config in configs.values():
                config[key] = value

    if resolve_env:
        import os
        import re

        env_var_pattern = re.compile(r'\$\{([^}]+)\}')
        for config in configs.values():
            for key, value in config.items():
                if isinstance(value, str):
                    matches = env_var_pattern.findall(value)
                    for match in matches:
                        env_var = os.getenv(match)
                        if env_var is not None:
                            value = value.replace(f'${{{match}}}', env_var)
                            config[key] = value
                        else:
                            error_record = logging.makeLogRecord({
                                'levelno': logging.ERROR,
                                'levelname': 'ERROR',
                                'name': 'config_loader',
                                'msg': f"Environment variable {match} not found for config value: {value}"
                            })
                            errors.append(error_record)

    return configs, errors

