                                       msg=f"Error parsing configuration file {filename}: {str(e)}", args=(), exc_info=True)
            errors.append(record)

    # Apply overrides if provided
    if overrides:
        for key, value in overrides.items():
            for config in configs.values():
                config[key] = value

    # Resolve environment variables if specified
    if resolve_env:
        for filename, config in configs.items():
            try:
                resolved_config = {k: v.format(**os.environ) if isinstance(v, str) else v for k, v in config.items()}
                configs[filename] = resolved_config
            except KeyError as e:
                record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0,
                                           msg=f"Environment variable not found in {filename}: {str(e)}", args=(), exc_info=True)
