                    config = yaml.safe_load(raw_config)
                else:
                    errors.append(logging.LogRecord(name='config_loader', level=logging.ERROR, msg=f"Unsupported file type: {filename}", pathname=filename, lineno=0))
                    continue

                if resolve_env:
                    config = {k: os.path.expandvars(v) for k, v in config.items()}

                if overrides:
                    config.update(overrides)

                configs[filename] = config

            except Exception as e:
                errors.append(logging.LogRecord(name='config_loader', level=logging.ERROR, msg=f"Error parsing {filename}: {str(e)}", pathname=filename, lineno=0))
