def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = self.parsers[parser_name]
    for arg, value in values_dict.items():
        action = [action for action in parser._actions if action.dest == arg]
        if action:
            type_func = action[0].type
            if type_func:
                try:
                    values_dict[arg] = type_func(value)
                except ValueError:
                    pass

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = self.parsers[parser_name]
    for arg, value in vars(parser.parse_args(namespace=SimpleNamespace(**values_dict))).items():
        if value != parser.get_default(arg):
            values_dict[arg] = value

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = self.parsers[parser_name]
    for arg, value in values_dict.items():
        if arg in parser._option_string_actions:
            action = parser._option_string_actions[arg]
            if isinstance(action.type, type):
                try:
                    values_dict[arg] = action.type(value)
                except (TypeError, ValueError) as e:
                    raise ValueError(f"Invalid value for {arg}: {value}") from e
        elif arg in parser._option_string_actions.values():
            for option_string, action in parser._option_string_actions.items():
                if action.dest == arg:
                    if isinstance(action.type, type):
                        try:
                            values_dict[arg] = action.type(value)
                        except (TypeError, ValueError) as e:
                            raise ValueError(f"Invalid value for {arg}: {value}") from e
                    break

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    plugin_spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
    if not os.path.exists(plugin_spec_path):
        return {}

    with open(plugin_spec_path, 'r') as file:
        plugin_spec = json.load(file)

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(plugin_spec)

